import{c as t,Z as l,Q as r,j as s,g as e,n,o,m as d}from"./chunks/framework.BnKG8mJY.js";const f=JSON.parse('{"title":"Admin Guide","description":"","frontmatter":{"title":"Admin Guide","outline":"deep"},"headers":[],"relativePath":"guide/admin-guide.md","filePath":"guide/admin-guide.md"}'),u={name:"guide/admin-guide.md"},m={id:"admin-guide",tabindex:"-1"};function k(h,a,g,b,p,c){const i=l("Badge");return r(),s("div",null,[e("h1",m,[a[0]||(a[0]=n("Admin Guide ",-1)),o(i,{type:"tip",text:"^0.3"}),a[1]||(a[1]=n()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#admin-guide","aria-label":'Permalink to "Admin Guide <Badge type="tip" text="^0.3" />"'},"​",-1))]),a[3]||(a[3]=d('<h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Panduan ini menjelaskan tugas admin dalam mengelola data, pengguna, dan konfigurasi sistem TMS.</p><h2 id="peran-hak-akses-admin" tabindex="-1">Peran &amp; Hak Akses Admin <a class="header-anchor" href="#peran-hak-akses-admin" aria-label="Permalink to &quot;Peran &amp; Hak Akses Admin&quot;">​</a></h2><ul><li>Mengelola master data dan transaksi.</li><li>Mengatur akun pengguna dan hak akses.</li><li>Melakukan monitoring serta audit aktivitas.</li></ul><h2 id="manajemen-pengguna" tabindex="-1">Manajemen Pengguna <a class="header-anchor" href="#manajemen-pengguna" aria-label="Permalink to &quot;Manajemen Pengguna&quot;">​</a></h2><h3 id="tambah-user" tabindex="-1">Tambah user <a class="header-anchor" href="#tambah-user" aria-label="Permalink to &quot;Tambah user&quot;">​</a></h3><ul><li>Masuk ke menu admin pengguna.</li><li>Isi data user baru dan simpan.</li></ul><h3 id="assign-role" tabindex="-1">Assign role <a class="header-anchor" href="#assign-role" aria-label="Permalink to &quot;Assign role&quot;">​</a></h3><ul><li>Pilih role sesuai fungsi (admin atau user).</li><li>Pastikan role konsisten dengan kebutuhan operasional.</li></ul><h2 id="pengelolaan-data-transaksi" tabindex="-1">Pengelolaan Data Transaksi <a class="header-anchor" href="#pengelolaan-data-transaksi" aria-label="Permalink to &quot;Pengelolaan Data Transaksi&quot;">​</a></h2><ul><li>Verifikasi transaksi Sales Cost dan Subcontractor.</li><li>Pastikan data yang diinput sesuai dokumen pendukung.</li></ul><h2 id="pengelolaan-subcontractor" tabindex="-1">Pengelolaan Subcontractor <a class="header-anchor" href="#pengelolaan-subcontractor" aria-label="Permalink to &quot;Pengelolaan Subcontractor&quot;">​</a></h2><ul><li>Update data subcontractor dan hubungan kerja.</li><li>Pastikan status kontrak dan biaya selalu valid.</li></ul><h2 id="manajemen-event-kalender" tabindex="-1">Manajemen Event Kalender <a class="header-anchor" href="#manajemen-event-kalender" aria-label="Permalink to &quot;Manajemen Event Kalender&quot;">​</a></h2><ul><li>Tambah event untuk aktivitas operasional penting.</li><li>Update event agar user melihat informasi terbaru.</li></ul><h2 id="monitoring-audit" tabindex="-1">Monitoring &amp; Audit <a class="header-anchor" href="#monitoring-audit" aria-label="Permalink to &quot;Monitoring &amp; Audit&quot;">​</a></h2><ul><li>Tinjau perubahan data melalui audit log.</li><li>Pastikan setiap perubahan memiliki jejak yang jelas.</li></ul><h2 id="keamanan-kontrol-akses" tabindex="-1">Keamanan &amp; Kontrol Akses <a class="header-anchor" href="#keamanan-kontrol-akses" aria-label="Permalink to &quot;Keamanan &amp; Kontrol Akses&quot;">​</a></h2><ul><li>Gunakan password kuat dan lakukan rotasi berkala.</li><li>Batasi akses berdasarkan kebutuhan peran.</li></ul><h2 id="best-practices-admin" tabindex="-1">Best Practices Admin <a class="header-anchor" href="#best-practices-admin" aria-label="Permalink to &quot;Best Practices Admin&quot;">​</a></h2><ul><li>Lakukan validasi data sebelum disimpan.</li><li>Simpan dokumentasi perubahan penting.</li><li>Koordinasikan perubahan besar dengan tim terkait.</li></ul><h2 id="pengembangan-lanjutan" tabindex="-1">Pengembangan Lanjutan <a class="header-anchor" href="#pengembangan-lanjutan" aria-label="Permalink to &quot;Pengembangan Lanjutan&quot;">​</a></h2><ul><li>Evaluasi kebutuhan fitur baru berdasarkan feedback pengguna.</li><li>Dokumentasikan perubahan skema data dan API.</li></ul><h2 id="troubleshooting-admin" tabindex="-1">Troubleshooting Admin <a class="header-anchor" href="#troubleshooting-admin" aria-label="Permalink to &quot;Troubleshooting Admin&quot;">​</a></h2><ul><li>Gagal login: verifikasi kredensial dan status akun.</li><li>Data tidak tersimpan: cek validasi input dan koneksi backend.</li><li>User tidak bisa akses menu: periksa role dan izin.</li><li>Grafik tidak tampil: pastikan API dashboard berjalan dan tidak error.</li><li>Audit log kosong: cek layanan logging dan koneksi database.</li></ul>',25))])}const q=t(u,[["render",k]]);export{f as __pageData,q as default};
